window.kbPageData["views/entry/k-2131d8122d4eaf04"] = {"key":"entry/k-2131d8122d4eaf04","state":{"route":"entry/k-2131d8122d4eaf04"},"node":{"id":"k-2131d8122d4eaf04","mode":"k","title":"平均数的同比增长量","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["平均数的同比增长量公式"],"qs":["国考 2025 副省级 行测#131"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"平均数的同比增长量等于现期平均数减去上年同期平均数。设总量和份数的同比增速分别为 a 和 b，则同比增长量等于现期平均数乘以 (a−b)/(1+a)。","review":{"definition":"平均数的同比增长量等于现期平均数减去上年同期平均数。设总量和份数的同比增速分别为 a 和 b，则同比增长量等于现期平均数乘以 (a−b)/(1+a)。","explanation":"把现期总量和份数分别除以 1+a 和 1+b，可还原上年同期数据，因此上年同期平均数等于现期平均数乘以 (1+b)/(1+a)。本题中，支付总金额增长 6.97%，低于业务笔数的增速 12.59%，所以平均每笔金额下降。现期平均每笔金额为 3151.37 万亿元除以 3358.88 亿笔，约为 9382 元，乘以 (6.97%−12.59%)/(1+6.97%)，得到同比减少约 493 元，选 A。","references":[],"evidence":"支付系统共处理支付业务3358.88亿笔，金额3151.37万亿元，同比分别增长12.59%和6.97%。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#131":{"paper":"国考 2025 副省级 行测","n":131,"mod":"资料分析","src":["ffe12c35a46d4df574ec.pdf",27],"asrc":["ff0b352b44d417525086.pdf",41],"card":"fc9fb0f628a0cc41904be05b","links":[{"id":"k-2131d8122d4eaf04","role":"解题依据","why":"设总金额和总笔数的同比增速分别为 a 和 b，则平均每笔金额的同比增长量等于现期平均每笔金额乘以 (a−b)/(1+a)。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-2131d8122d4eaf04":[["国考 2025 副省级 行测#131"]]}};
